package ru.stepanov.simulacrum.application.usecase.transaction;
import org.springframework.stereotype.Service;import ru.stepanov.simulacrum.domain.model.shared.Money;import ru.stepanov.simulacrum.domain.model.transaction.*;import ru.stepanov.simulacrum.domain.repository.TransactionHistoryRepository;
import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;
@Service public class SubmitDebitUseCase { private final TransactionHistoryRepository repo; public SubmitDebitUseCase(TransactionHistoryRepository repo){this.repo=repo;} public TransactionHistory execute(String consentId, String sourceAccountId, String recipientToken, BigDecimal amount, String currency){String txId="TX-DEBIT-"+UUID.randomUUID().toString().substring(0,8); var tx=new TransactionHistory(txId,sourceAccountId,TransactionStatusCode.Pending,BankTransactionCode.ObPayment,Instant.now(),Instant.now(),new Money(amount,currency),CreditDebitCode.Debit,recipientToken,"RECIPIENT",null,sourceAccountId,recipientToken); repo.save(tx); tx.complete(); return repo.save(tx);} }
